#ifndef PROCULUS_UI_ASSETS_HPP
#define PROCULUS_UI_ASSETS_HPP

#include <vector>

namespace proculus {

struct UiAsset {
	const char* path; // as requested, e.g. "/app.js"
	const char* mime;
	const char* content;
};

// The files of services/ui/web/, compiled into the binary (generated by CMake)
// so nothing has to be installed next to it.
const std::vector<UiAsset>& ui_assets();

} // namespace proculus

#endif // PROCULUS_UI_ASSETS_HPP
